INSERT INTO purpose VALUES('runtime-emitter','PATCHER','constant','States whether this host has a patcher, so native code runs here.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','block::Answer','enum','Names the word that a block returns: zero, or the value that a register or a register of a class holds on exit.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','block::Assembler','struct','The path of the llc that compiles each block, by default the llc of the toolchain that built the crate.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','block::Block','struct','One compiled block: its key, its target, its bytes and where a request found them.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','block::Blocks','struct','The block compiler: it compiles a description by llc in a process of its own and keeps the bytes under the digest of the description, in the process and in a directory.','sharing','fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','block::Cache','enum','Names where a block compiler keeps its bytes: in the process alone, or in a directory too.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','block::Class','enum','Names a class of registers from which LLVM picks the register of an operand.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','block::Code','struct','The machine code of one block: the text of its object, entered at its first byte.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','block::Description','struct','The data that the bytes of a block are a function of: the target, the template, the operands, the answer, the clobbers and the options.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','block::Direction','enum','Names how an operand passes between its word and its register: in, out, or in and out.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','block::Flags','enum','Names whether the template of a block can change the flags of the target.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','block::Key','struct','The digest of the description of a block, which names the block in a function and in the table of blocks of the process.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','block::Memory','enum','Names whether the template of a block can touch memory.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','block::Operand','struct','One operand of a block: its direction and the register or class that holds its word.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','block::Options','struct','The options of a block, as the options of Rust''s asm! state them: whether it touches memory and whether it changes the flags.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','block::Origin','enum','Names where a request found the bytes of a block: its own compile, the process, or the directory.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','block::Place','enum','Names where an operand or the answer of a block is: one named register, or a register of a class.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','block::Refusal','enum','Names why a description gives no block: an absent llc, a missing register, a bad reference, a refused template, a relocation, an undefined symbol, a count of code sections other than one, an object that does not parse, or a failed process or file.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','block::Register','struct','The name of one register of a target, as LLVM spells it.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','block::Target','enum','Names a target that a block compiles for, with the arguments that select it in llc.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','block::Template','struct','The instructions of a block in the syntax of Rust''s asm!, each reference naming an operand or the answer.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','budget::Budget','struct','The jump budget of a run and where it comes from: the invocation''s flag, a server''s budget, the caller''s count, or no budget.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','budget::Jumps','struct','A count of code-word jumps above zero, read from the decimal digits of a flag.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','budget::Origin','enum','Names where a run''s jump budget comes from: the invocation''s flag, the budget of a server whose invocation names none, the caller of the run, or no budget.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','budget::Spent','struct','The stop of a run that spent its jump budget: the count, the budget with its origin, and the remedy of that origin.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','budget::Uncounted','enum','Names why a text names no count of jumps: a character that is not a decimal digit, a count past 64 bits, or zero.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','budget::bind','function','Binds the invocation''s jump budget once, before its first run, and returns the budget in force when an earlier binding fixed it.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','budget::bound','function','Reads the jump budget each run that the dispatcher starts takes: the budget that bind gave, else no budget.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','crossing::CrossingRefusal','enum','Names why a value did not cross: it holds a value that does not cross, it reaches an address its store does not bind, the value plane refused its encoding or profile, or the destination store refused an allocation.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','crossing::Uncrossable','enum','Names what a value that does not cross is: a stack, a thunk, a fixpoint, a closure, an opaque constant, a code, a capability, an accumulator, a recorded run, a dialogue or a web.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','crossing::commit','function','Commits the value a store binds to the value plane under the crossing profile, refusing a value that does not cross before anything is written.','sharing','fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','crossing::deref','function','Reads a committed value back into a store at addresses fresh there, refusing a profile other than the crossing profile before any chunk is read.','sharing','fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','crossing::profile','function','Builds the value-plane profile a crossing commits and reads under from the deployment''s chunker constants and this codec''s identity.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','cut::evaluate_scheduled_on','function','Runs a scheduled program on the caller''s fork, its root and writers lowered once: each spawn copies its writer''s thunk into a store of its own and starts it, and each read waits for that writer and copies its answer back.','fork','fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','executable::MapFailure','struct','Names why mapping a region failed: the host''s error number, or zero on a host with no mapping.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','function::Alt','enum','Names the second continuation of an instruction: none for a one-way stencil, or the label a two-way stencil continues at on a match.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','function::BlockRow','struct','Names a block as an index into the function''s table of block keys.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','function::Constant','struct','Names a word offset into a function''s constants.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','function::Function','struct','Holds a lowered function: the straight list of stencil instructions both tiers run, its labels, its constants and its entry window''s slot count, compared and hashed by value as the cache key.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','function::Immediate','struct','Holds an immediate operand: a slot, a count, an ordinal or half a header, below 2 to the 32nd so either patcher materialises it.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','function::Instruction','struct','Holds one stencil instruction: the stencil, its two operands, and the second continuation of a two-way stencil.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','function::Label','struct','Names a label as an index into the function''s label table, bound to one instruction.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','function::Operand','enum','Names what an operand hole receives: nothing, an immediate, the address of a labelled instruction''s code, a constant, a shared frame stub, or the address of a block.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','function::Position','struct','Names an instruction''s index in its function.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','function::Slots','struct','Holds a count of window slots.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','function::Stub','enum','Names a frame stub every function shares: the code a frame whose second word is a value, never a window, resumes.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','function::Unbound','enum','Names a label no instruction is bound to, or a block row past the function''s table of blocks.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','fuse::Dispatches','struct','Holds how many dispatches a function''s instructions cost, one per stencil.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','fuse::Fused','struct','Records one fusion: the position, in the unfused function, of the pair''s first instruction, and the rule that fused it.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','fuse::FusionRefusal','enum','Names why a replay refused a decision: the position does not hold the rule''s left side, a label enters the pair, or the decision does not follow the one before it.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','fuse::Rule','enum','Names a rewrite of the instruction alphabet: two stencils in sequence, the first''s value handed to the second in the value register, run as one.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','fuse::dispatches','function','Counts the dispatches a function costs, one per instruction, the stencil table''s charge for every stencil.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','fuse::replay','function','Re-derives the function a trace fuses from the unfused one and the decisions alone, in order, searching for nothing, refusing a forged, entered or unordered decision by name.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','host::release','function','Releases an object and its owners: every object whose count reaches zero has its block on the free list of its size, and every other value counts one owner fewer.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','image::ImageRefusal','enum','Names why a command has no image or why bytes give no command: a form the image does not write, a dangling node, an undefined constant, the value plane''s refusal, a constant defined twice, a refused node or mark, a root that does not check closed, a table of annotations that the node codec refuses, or an annotation that does not mint.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','image::Read','struct','A command read from its image: a fresh arena that holds its nodes alone, the definitions that it unfolds, and its root.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','image::Uncodable','enum','Names a node form that the image does not write: a constructor head that does not cross.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','image::encode','function','Writes the canonical bytes of the command that a root reaches, with the definitions that it unfolds, so equal commands give equal bytes.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','image::read','function','Mints the command that bytes write into a fresh arena and judges its root again with check_command.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','lower::Bound','struct','Records a bind frame a reified stack holds: what moves a stack in the run''s answer into the caller''s store.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','lower::Callee','enum','Names what a host call does, by its number in the function''s callee table.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','lower::Cell','struct','Records a fold''s cell closure: it lives only in the frame that applies it, so no site records it, and it owns one reference of each producer it captures.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','lower::Clause','struct','Records an operation clause of a handler: the operation it answers, the clause''s label, the slot of the handler''s window a capturing clause''s payload is written to, and the path an operation takes to it.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','lower::Form','enum','Names a command the lowering does not lay out: one ill-formed, or one past a width the layout holds.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','lower::Handler','struct','Records a handler the function installs: what an operation''s capture finds by the code of the handler''s frame.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','lower::Lowered','struct','Holds a lowered command: the function, its closure sites and the tables its objects and calls name.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','lower::OwnerRun','struct','Records a run of the owner table: the slots a frame owns while it waits, one entry per owner.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','lower::Path','enum','Names how an operation reaches its clause, read off the clause''s body: on the frames left standing under a marker, resumed or returned from, or with the frames captured into a stack.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','lower::Reach','enum','Names how an operation finds its handler: the nearest delimiter decides, or the handler that introduced the capability decides.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','lower::Reified','enum','Names a frame of a reified stack: an application, a projection, or a bind frame resuming at a label in a copy of the window.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','lower::Site','struct','Records a closure the function creates: what moves a closure in the run''s answer into the caller''s store.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','lower::Slot','struct','Names a slot of a window.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','lower::Window','struct','Records a label a frame resumes at in a window: what a capture copies of the window, and which of the copied values the frame owns.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','lower::lower','function','Lowers the closed command, then fuses its adjacent pairs, refusing the form of the first ill-formed or oversized node.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','lower::lower_open','function','Lowers a command delivering to the halt as a function opened over the producer bindings its support selects in the entry window''s first slots: the code an open endpoint runs, each free variable an accumulator.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','lower::lower_unfused','function','Lowers the closed command, every instruction its own dispatch: the function a fused one''s trace is replayed over.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','machine::Unentered','enum','Names why the key of a block gives no address: no compile gave the key, the block is for another target, or the host refused the mapping.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','machine::address','function','Gives the address of a block in this process, and maps its bytes executable on the first request.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','native::EmitRefusal','enum','Names why emission failed: a region mapping failed, the function is larger than a region, a hole could not be patched, a label is unbound, the last instruction falls off, or an operand is missing.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','native::PatchRefusal','enum','Names why a hole could not be patched: a branch target beyond reach, an address beyond page reach, a value past its field, a wrong shape, or a wrong kind.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','regions::Bytes','struct','A size in bytes, read from its spelling with a unit and written with its digits grouped.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','regions::Charge','struct','What the process''s own cgroup charges against its memory.max: the bytes charged, and the count of times the charge met the bound.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','regions::Held','struct','A run''s stop at its memory bound: what each region held, at which step, and which region asked for the chunk that did not fit.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','regions::Memory','struct','The memory bound of the runs of one invocation, and where it comes from.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','regions::Origin','enum','Names where a run''s memory bound comes from: the invocation''s flag, the memory the host makes available, the memory.max of the process''s cgroup, half of its physical memory, or the bound of a host that reports none.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','regions::Reached','struct','A count of the times a cgroup''s charge met its memory.max, so a walk ends when the count rises past its start.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','regions::Region','enum','Names the region that asked for the chunk a run could not commit: the heap or the window region.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','regions::Short','enum','Names what a region found short of the chunk it asked for: the bound, or its reservation.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','regions::Spelled','struct','Writes a size as its largest unit that divides it.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','regions::Standing','enum','Names the account of the process''s address space at a stop at a reservation: the share, what the budget holds and the space, or a host that reports no space.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','regions::Step','struct','The code-word jumps a run spent before it stopped.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','regions::Unsized','enum','Names why a text names no size: no digit, an unknown unit, a zero size, or a size past 64 bits.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','regions::bind','function','Binds the invocation''s memory bound once, before its first run, and returns the bound in force when an earlier binding fixed it.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','regions::bound','function','Reads the memory bound every run of the process takes: the bound that bind gave, else the host''s, read once.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','regions::charge','function','Reads what the process''s own cgroup charges, so a walk under a cgroup''s memory.max ends by the bound''s name before the kernel ends it; none outside such a cgroup.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','regions::resident','function','Reads the bytes the process holds in memory, so a walk compares them against the memory bound; none on a host that reports none.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','run::Choice','enum','Names the tier a run asks for: the one the process''s policy picks, or one tier.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','run::Declined','enum','Names why a run gave no outcome: a form the lowering refused, no patcher, an emission refusal, an unbound label, a cache miss, a stuck run, a spent jump budget with its origin, a frame region past its bound, a stop at the memory bound, a transfer refusal, or a reply the run cannot hold.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','run::Kept','struct','Keeps the emitted code a lowering''s first native run found, so a later run of the same lowering takes no cache lookup.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','run::POLICY_VARIABLE','constant','Names the environment variable the policy is read from.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','run::Policy','enum','Names when a run takes native code: emit on a function''s first run and serve the cache after, never emit, or serve only cached code.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','run::RunInputs','struct','Holds what a run reads besides its program and its fuel: the store its outcome moves into, the store''s values it is closed over, the host its unclaimed operations are offered to, and whether it records its channels.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','run::Tier','enum','Names which code a run takes: emitted native code served from the cache, or the portable executor.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','run::evaluate','function','Runs the command on the tier the policy picks, the executor wherever native code is not to be had, and moves its outcome into the caller''s store.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','run::evaluate_on','function','Runs the command on the named tier with the given fuel and moves its outcome into the caller''s store; an operation no handler of the run claims stops it stuck.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','run::evaluate_on_with_host','function','Runs the command on the named tier, an operation no handler of the run claims offered to the host once, its payload moved into the store.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','run::evaluate_open','function','Runs an open command on the tier the policy picks, each free variable bound to an accumulator, and moves its outcome into the caller''s store, where an accumulator reads back as the neutral it spells.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','run::evaluate_open_on','function','Runs an open command on the named tier, each free variable bound to an accumulator, and moves its outcome into the caller''s store.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','run::evaluate_unfused_on','function','Runs the command''s unfused lowering on the named tier: every instruction its own dispatch, the reference a fused function answers to.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','run::evaluate_with_host','function','Runs the command on the tier the policy picks, an operation no handler of the run claims offered to the host.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','seam::HostHandler','trait','Decides the operations a run offers, without access to its frames: a reply continues the operation''s continuation, an abort stops the run, and a decline leaves the operation unhandled.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','seam::HostOutcome','enum','Names how a run with a host ended: the run halted or stopped stuck, or the host stopped the run instead of replying.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','seam::HostReply','enum','Names a host''s decision about one offered operation: deliver a value to the operation''s continuation, stop without resuming, or leave the operation unhandled.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','seam::HostRequest','struct','Names an operation no handler of the run claims: the inline interface, the requested operation, and the payload moved into the caller''s store.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','seam::HostValues','struct','Gives the host its value capability over the caller''s store: inspect, allocate and read back, never alter frames.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','seam::Migrated','enum','Names a host''s decision about one migration: run it in this process, take the answer crossed back from where it ran, or refuse it for a reason.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','seam::MigrationRequest','struct','Names a migration a run is about to make: the world it names, its command, and the captures its body binds, values of the caller''s store.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','seam::Spawning','enum','Names where a cut''s writer runs: apart, its spawn offered to the host that starts it, or in place, forced where its reader awaits its answer.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','seam::TaskOrder','enum','Names the order in which a run''s scheduler takes its ready tasks: the oldest first, or the newest first.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','trace::Carried','enum','Names what a traced send carried and its receipt took: a value of the caller''s store, or a delegated channel end.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','trace::ChannelNumber','struct','Numbers a traced run''s channels in the order their forks ran, so a delegated end names its channel.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','trace::Play','struct','Holds one channel''s play, its fork and its moves in the order made, so its causal web is read as a dialogue''s is.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','trace::Played','struct','Holds one move of a play: the task that made it, the end it made it at, and the move.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','trace::TaskNumber','struct','Numbers a traced run''s tasks, the root zero and each child in the order its fork ran, so a move names its maker.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','trace::Trace','struct','Holds a traced run''s plays, one per channel in the order its fork ran.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','transfer::TransferRefusal','enum','Names why an answer could not be moved into the store: the store refused an allocation, a header names no kind, a code word names no site, a site''s producer is wrong, the graph holds a cycle, a table entry is missing, or a host object reached the answer.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','widths::description','function','Gives the description of the block that computes one operation of a width on a target, its answer cut to the width.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','world::Attenuated','struct','Attenuates a host to a world''s row: an operation of an interface the row names goes to the host, and every other operation is declined, so a shipped body reaches only what its world requires.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','world::arrive','function','Runs here a migration another host shipped, by its command in the program both hosts hold, over captures read into the store, under the handler of the host that runs it, refusing a command that is no migration to this world before anything runs.','sharing','fits','sound',NULL);
INSERT INTO purpose VALUES('runtime-emitter','world::chunking','function','Gives the chunker constants every crossing between worlds commits and reads under, in this process and between hosts.','sharing','fits','sound',NULL);
